// Returning to the best-performing strategy (attempt 1, 40.8% / 91.8%) with
// exactly one mechanical fix: replace `next == "<<"` exact-token test with
// `RenderedEndsWith(generated, "<<")`, which is required because a tokenizer
// may attach whitespace to or split "<<" across two tokens, making exact
// equality miss the delimiter and preventing any span from ever opening.
//
// All other logic is preserved from the best attempt:
// - Free unconstrained generation for the reasoning chain.
// - Transition to constrained mode the moment rendered output ends with "<<".
// - AdaptiveConstrainedStep with validTokenGroups soft-boosts inside spans.
// - CloseConstrainedSpan as soon as IsCompletePrefix holds.
// - CloseSpanWithinBudget near budget exhaustion.
// - Force-open via OpenConstrainedSpan when fewer than 4 steps remain and no
//   span has opened yet, guaranteeing at least one constrained expression.
//
// Attempt 65 regressed to 0% because it called SpeculativeConstrainedRollout,
// which is not in the allowed helper set, causing a runtime error on every
// example. This attempt removes that call entirely.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span branch: insideConstrainedOut is false; implication vacuous.
//   When RenderedEndsWith(generated, "<<") fires, EnterObservedConstrainedSpan
//   sets currentConstrainedOut := [], and parser.IsValidPrefix([]) holds by
//   method precondition. OpenConstrainedSpan (force-open path) likewise sets
//   currentConstrainedOut := [] with the same guarantee ✓.
//
//   CloseConstrainedSpan branch: sets insideConstrainedOut := false, making
//   the implication vacuously true; currentConstrainedOut becomes [] ✓.
//
//   CloseSpanWithinBudget branch: its postcondition explicitly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut) ✓.
//
//   AdaptiveConstrainedStep + AppendConstrainedToken: AdaptiveConstrainedStep
//   uses a hard parser mask and returns EOS or a parser-valid next token.
//   AppendConstrainedToken extends currentConstrainedOut by that one valid
//   token, preserving IsValidPrefix by IsTokenValidNext ✓.
//   The EOS path breaks without calling AppendConstrainedToken ✓.
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: equality holds (steps = 0) ✓.
//
//   UnconstrainedStep: steps += 1; generated grows by at most 1 (EOS path
//   breaks without appending). EnterObservedConstrainedSpan leaves generated
//   unchanged ✓.
//
//   OpenConstrainedSpan (force-open): appends "<<" (1 token) and steps += 1 ✓.
//
//   AdaptiveConstrainedStep + AppendConstrainedToken: steps += 1 and
//   AppendConstrainedToken appends exactly 1 token ✓.
//
//   CloseConstrainedSpan: appends ">>" (1 token) and steps += 1 ✓.
//
//   CloseSpanWithinBudget with closeBudget = maxSteps - steps: postcondition
//   gives |generated_new| <= |generated_old| + closeBudget; after
//   steps := maxSteps the bound becomes |generated| <= |generatedPrefix| +
//   maxSteps = |generatedPrefix| + steps ✓.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Wrap every intermediate symbolic expression and the " +
  "final numeric answer inside << >> delimiters. " +
  "Example: The total is <<3+4=7>> dollars.");

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    // Budget pressure: force-open a constrained span for the final answer.
    if maxSteps - steps <= 4 && steps > 0 {
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        // Use RenderedEndsWith to detect "<<" even when the tokenizer attaches
        // whitespace or splits the delimiter across tokens.
        if RenderedEndsWith(generated, "<<") {
          var og, oi, oc := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := og;
          insideConstrainedOut := oi;
          currentConstrainedOut := oc;
        }
      }
    }
  } else {
    // Inside a constrained span.
    if parser.IsCompletePrefix(currentConstrainedOut) {
      // Span is complete: close it immediately.
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 3 {
      // Near budget end: use CloseSpanWithinBudget to finish gracefully.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Normal constrained generation: one hard-masked parser-valid token.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

